package com.arjunren.leave.entity;
import com.arjunren.leave.domain.*; import jakarta.persistence.*; import java.time.*;
@Entity@Table(name="leave_requests",indexes={@Index(name="leave_employee_dates_idx",columnList="employee_id,start_date,end_date"),@Index(name="leave_status_idx",columnList="status")})public class LeaveRequest{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false,fetch=FetchType.LAZY)@JoinColumn(name="employee_id")private EmployeeProfile employee;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private LeaveType type;@Column(name="start_date",nullable=false)private LocalDate startDate;@Column(name="end_date",nullable=false)private LocalDate endDate;@Column(name="total_days",nullable=false)private int totalDays;@Column(nullable=false,length=500)private String reason;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private LeaveStatus status=LeaveStatus.PENDING;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="reviewed_by")private AppUser reviewedBy;@Column(name="review_note",length=500)private String reviewNote;@Column(name="decided_at")private Instant decidedAt;@Version private long version;@Column(name="created_at",nullable=false,updatable=false)private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false)private Instant updatedAt=Instant.now();protected LeaveRequest(){}public LeaveRequest(EmployeeProfile e,LeaveType t,LocalDate s,LocalDate end,int days,String reason){employee=e;type=t;startDate=s;endDate=end;totalDays=days;this.reason=reason;}@PreUpdate void ts(){updatedAt=Instant.now();}public void approve(AppUser u,String note){status=LeaveStatus.APPROVED;reviewedBy=u;reviewNote=note;decidedAt=Instant.now();}public void reject(AppUser u,String note){status=LeaveStatus.REJECTED;reviewedBy=u;reviewNote=note;decidedAt=Instant.now();}public void cancel(){status=LeaveStatus.CANCELLED;}public Long getId(){return id;}public EmployeeProfile getEmployee(){return employee;}public LeaveType getType(){return type;}public LocalDate getStartDate(){return startDate;}public LocalDate getEndDate(){return endDate;}public int getTotalDays(){return totalDays;}public String getReason(){return reason;}public LeaveStatus getStatus(){return status;}public String getReviewNote(){return reviewNote;}public Instant getCreatedAt(){return createdAt;}public Instant getUpdatedAt(){return updatedAt;}}

